import type {} from "cordis";

export type TagColor = "slate" | "sky" | "emerald" | "amber" | "rose" | "violet";

export interface Tag {
  readonly id: string;
  readonly name: string;
  readonly color: TagColor;
  readonly createdAt: string;
}

export interface TagWithUsage extends Tag {
  readonly taskCount: number;
}

export interface CreateTagInput {
  readonly name: string;
  readonly color?: TagColor;
}

export interface TodoTagsSummary {
  readonly tags: readonly TagWithUsage[];
  readonly assignments: Readonly<Record<string, readonly Tag[]>>;
}

export interface TodoTagsChangedPayload {
  readonly taskId: string | null;
  readonly tagId?: string;
}

export interface TodoTagsService {
  listTags(): TagWithUsage[];
  createTag(input: CreateTagInput): Tag;
  deleteTag(id: string): boolean;
  listTaskTags(taskId: string): Tag[];
  setTaskTags(taskId: string, tagIds: readonly string[]): Tag[];
  addTaskTag(taskId: string, tagId: string): Tag[];
  removeTaskTag(taskId: string, tagId: string): Tag[];
  summary(): TodoTagsSummary;
}

declare module "cordis" {
  interface Context {
    todoTags: TodoTagsService;
  }
  interface Events {
    "todo-tags:changed"(payload: TodoTagsChangedPayload): void;
  }
}

