", "sourceFiles": {"server.ts": "import { Service, type Context } from "cordis";
import type { ScopedDb } from "@host/server-sdk";
import type {
  CreateTagInput,
  Tag,
  TagColor,
  TagWithUsage,
  TodoTagsService,
  TodoTagsSummary,
} from "./contract.d.ts";

const TAG_COLORS: readonly TagColor[] = [
  "slate",
  "sky",
  "emerald",
  "amber",
  "rose",
  "violet",
];
const MAX_TAG_NAME_LENGTH = 32;

interface TagRow {
  readonly id: string;
  readonly name: string;
  readonly color: string;
  readonly created_at: string;
}

interface TagWithUsageRow extends TagRow {
  readonly task_count: number;
}

interface AssignmentRow extends TagRow {
  readonly task_id: string;
}

interface TodoTaskRef {
  readonly id: string;
}

interface TodoGateway {
  get(id: string): TodoTaskRef | null;
  list(filter?: {
    readonly state?: "open" | "done";
  }): ReadonlyArray<TodoTaskRef>;
}

function httpError(status: number, message: string): Error & { status: number } {
  const error = new Error(message) as Error & { status: number };
  error.status = status;
  return error;
}

function isTagColor(value: unknown): value is TagColor {
  return (
    typeof value === "string" &&
    (TAG_COLORS as readonly string[]).includes(value)
  );
}

function normalizeColor(value: string): TagColor {
  return isTagColor(value) ? value : "slate";
}

function toTag(row: TagRow): Tag {
  return {
    id: row.id,
    name: row.name,
    color: normalizeColor(row.color),
    createdAt: row.created_at,
  };
}

function toTagWithUsage(row: TagWithUsageRow): TagWithUsage {
  return {
    ...toTag(row),
    taskCount: Number(row.task_count ?? 0),
  };
}

export default class TodoTagsPluginService
  extends Service
  implements TodoTagsService
{
  private readonly db: ScopedDb;

  constructor(ctx: Context) {
    super(ctx, "todoTags");
    this.db = ctx.db;

    this.db.exec(`CREATE TABLE IF NOT EXISTS plg_todo_tags__tags (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      color TEXT NOT NULL DEFAULT 'slate',
      created_at TEXT NOT NULL
    )`);
    this.db.exec(
      "CREATE UNIQUE INDEX IF NOT EXISTS plg_todo_tags__tags_name_ci ON plg_todo_tags__tags (name COLLATE NOCASE)",
    );
    this.db.exec(`CREATE TABLE IF NOT EXISTS plg_todo_tags__task_tags (
      task_id TEXT NOT NULL,
      tag_id TEXT NOT NULL,
      created_at TEXT NOT NULL,
      PRIMARY KEY (task_id, tag_id)
    )`);
    this.db.exec(
      "CREATE INDEX IF NOT EXISTS plg_todo_tags__task_tags_tag ON plg_todo_tags__task_tags (tag_id)",
    );

    ctx.http.route("GET", "/tags", () => ({ tags: this.listTags() }));

    ctx.http.route("POST", "/tags", (req) => {
      const body = (req.body ?? {}) as { name?: unknown; color?: unknown };
      if (typeof body.name !== "string" || body.name.trim().length === 0) {
        return { status: 400, body: { error: "Tag name is required" } };
      }
      let color: TagColor | undefined;
      if (body.color !== undefined) {
        if (!isTagColor(body.color)) {
          return {
            status: 400,
            body: { error: `Invalid tag color: ${String(body.color)}` },
          };
        }
        color = body.color;
      }
      const tag = this.createTag({ name: body.name, color });
      return { status: 201, body: { tag } };
    });

    ctx.http.route("DELETE", "/tags/:id", (req) => {
      const deleted = this.deleteTag(req.params.id);
      if (!deleted) {
        return { status: 404, body: { error: "Tag not found" } };
      }
      return { deleted: true, id: req.params.id };
    });

    ctx.http.route("GET", "/summary", () => this.summary());

    ctx.http.route("GET", "/tasks/:taskId/tags", (req) => ({
      tags: this.listTaskTags(req.params.taskId),
    }));

    ctx.http.route("POST", "/tasks/:taskId/tags", (req) => {
      const body = (req.body ?? {}) as { tagId?: unknown };
      if (typeof body.tagId !== "string" || body.tagId.length === 0) {
        return { status: 400, body: { error: "tagId is required" } };
      }
      return { tags: this.addTaskTag(req.params.taskId, body.tagId) };
    });

    ctx.http.route("PUT", "/tasks/:taskId/tags", (req) => {
      const body = (req.body ?? {}) as { tagIds?: unknown };
      if (
        !Array.isArray(body.tagIds) ||
        body.tagIds.some((tagId) => typeof tagId !== "string")
      ) {
        return {
          status: 400,
          body: { error: "tagIds must be an array of strings" },
        };
      }
      return {
        tags: this.setTaskTags(req.params.taskId, body.tagIds as string[]),
      };
    });

    ctx.http.route("DELETE", "/tasks/:taskId/tags/:tagId", (req) => ({
      tags: this.removeTaskTag(req.params.taskId, req.params.tagId),
    }));
  }

  private todoGateway(): TodoGateway {
    const gateway = (this.ctx as unknown as { todo?: TodoGateway }).todo;
    if (!gateway) {
      throw httpError(503, "Todo service is unavailable");
    }
    return gateway;
  }

  private requireTask(taskId: string): void {
    if (this.todoGateway().get(taskId)) return;
    this.db
      .prepare("DELETE FROM plg_todo_tags__task_tags WHERE task_id = ?")
      .run(taskId);
    throw httpError(404, "Task not found");
  }

  private getTag(id: string): Tag | null {
    const row = this.db
      .prepare(
        "SELECT id, name, color, created_at FROM plg_todo_tags__tags WHERE id = ?",
      )
      .get<TagRow>(id);
    return row ? toTag(row) : null;
  }

  listTags(): TagWithUsage[] {
    const rows = this.db
      .prepare(
        `SELECT t.id, t.name, t.color, t.created_at,
                (SELECT COUNT(*) FROM plg_todo_tags__task_tags tt WHERE tt.tag_id = t.id) AS task_count
         FROM plg_todo_tags__tags t
         ORDER BY t.name COLLATE NOCASE ASC, t.id ASC`,
      )
      .all<TagWithUsageRow>();
    return rows.map(toTagWithUsage);
  }

  createTag(input: CreateTagInput): Tag {
    const name = input.name.trim();
    if (!name) {
      throw httpError(400, "Tag name is required");
    }
    if (name.length > MAX_TAG_NAME_LENGTH) {
      throw httpError(
        400,
        `Tag name must be at most ${MAX_TAG_NAME_LENGTH} characters`,
      );
    }
    const color = input.color ?? "slate";
    if (!isTagColor(color)) {
      throw httpError(400, `Invalid tag color: ${String(color)}`);
    }
    const duplicate = this.db
      .prepare(
        "SELECT id FROM plg_todo_tags__tags WHERE name = ? COLLATE NOCASE",
      )
      .get<{ readonly id: string }>(name);
    if (duplicate) {
      throw httpError(409, `Tag already exists: ${name}`);
    }
    const id = globalThis.crypto.randomUUID();
    const createdAt = new Date().toISOString();
    this.db
      .prepare(
        "INSERT INTO plg_todo_tags__tags (id, name, color, created_at) VALUES (?, ?, ?, ?)",
      )
      .run(id, name, color, createdAt);
    this.ctx.emit("todo-tags:changed", { taskId: null, tagId: id });
    return { id, name, color, createdAt };
  }

  deleteTag(id: string): boolean {
    const existing = this.db
      .prepare("SELECT id FROM plg_todo_tags__tags WHERE id = ?")
      .get<{ readonly id: string }>(id);
    if (!existing) return false;
    this.db
      .prepare("DELETE FROM plg_todo_tags__task_tags WHERE tag_id = ?")
      .run(id);
    this.db.prepare("DELETE FROM plg_todo_tags__tags WHERE id = ?").run(id);
    this.ctx.emit("todo-tags:changed", { taskId: null, tagId: id });
    return true;
  }

  listTaskTags(taskId: string): Tag[] {
    this.requireTask(taskId);
    const rows = this.db
      .prepare(
        `SELECT t.id, t.name, t.color, t.created_at
         FROM plg_todo_tags__task_tags tt
         JOIN plg_todo_tags__tags t ON t.id = tt.tag_id
         WHERE tt.task_id = ?
         ORDER BY t.name COLLATE NOCASE ASC, t.id ASC`,
      )
      .all<TagRow>(taskId);
    return rows.map(toTag);
  }

  addTaskTag(taskId: string, tagId: string): Tag[] {
    this.requireTask(taskId);
    if (!this.getTag(tagId)) {
      throw httpError(404, "Tag not found");
    }
    this.db
      .prepare(
        "INSERT OR IGNORE INTO plg_todo_tags__task_tags (task_id, tag_id, created_at) VALUES (?, ?, ?)",
      )
      .run(taskId, tagId, new Date().toISOString());
    this.ctx.emit("todo-tags:changed", { taskId, tagId });
    return this.listTaskTags(taskId);
  }

  removeTaskTag(taskId: string, tagId: string): Tag[] {
    this.requireTask(taskId);
    this.db
      .prepare(
        "DELETE FROM plg_todo_tags__task_tags WHERE task_id = ? AND tag_id = ?",
      )
      .run(taskId, tagId);
    this.ctx.emit("todo-tags:changed", { taskId, tagId });
    return this.listTaskTags(taskId);
  }

  setTaskTags(taskId: string, tagIds: readonly string[]): Tag[] {
    this.requireTask(taskId);
    const uniqueIds = Array.from(
      new Set(tagIds.map((id) => id.trim()).filter((id) => id.length > 0)),
    );
    if (uniqueIds.length > 0) {
      const placeholders = uniqueIds.map(() => "?").join(", ");
      const found = this.db
        .prepare(
          `SELECT id FROM plg_todo_tags__tags WHERE id IN (${placeholders})`,
        )
        .all<{ readonly id: string }>(...uniqueIds);
      const known = new Set(found.map((row) => row.id));
      const missing = uniqueIds.filter((id) => !known.has(id));
      if (missing.length > 0) {
        throw httpError(400, `Unknown tag ids: ${missing.join(", ")}`);
      }
    }
    this.db
      .prepare("DELETE FROM plg_todo_tags__task_tags WHERE task_id = ?")
      .run(taskId);
    const insert = this.db.prepare(
      "INSERT OR IGNORE INTO plg_todo_tags__task_tags (task_id, tag_id, created_at) VALUES (?, ?, ?)",
    );
    const now = new Date().toISOString();
    for (const tagId of uniqueIds) {
      insert.run(taskId, tagId, now);
    }
    this.ctx.emit("todo-tags:changed", { taskId });
    return this.listTaskTags(taskId);
  }

  summary(): TodoTagsSummary {
    const gateway = this.todoGateway();
    const validTaskIds = new Set(gateway.list().map((task) => task.id));
    const assignedTaskRows = this.db
      .prepare("SELECT DISTINCT task_id FROM plg_todo_tags__task_tags")
      .all<{ readonly task_id: string }>();
    const removeOrphan = this.db.prepare(
      "DELETE FROM plg_todo_tags__task_tags WHERE task_id = ?",
    );
    for (const row of assignedTaskRows) {
      if (!validTaskIds.has(row.task_id)) {
        removeOrphan.run(row.task_id);
      }
    }

    const assignments: Record<string, Tag[]> = {};
    const rows = this.db
      .prepare(
        `SELECT tt.task_id AS task_id, t.id AS id, t.name AS name, t.color AS color, t.created_at AS created_at
         FROM plg_todo_tags__task_tags tt
         JOIN plg_todo_tags__tags t ON t.id = tt.tag_id
         ORDER BY t.name COLLATE NOCASE ASC, t.id ASC`,
      )
      .all<AssignmentRow>();
    for (const row of rows) {
      const bucket = assignments[row.task_id] ?? (assignments[row.task_id] = []);
      bucket.push(toTag(row));
    }

    return { tags: this.listTags(), assignments };
  }
}
", "client.tsx": "import { useCallback, useEffect, useMemo, useState } from "react";
import type { Context } from "cordis";
import type {} from "@host/client-sdk";
import { Check, Plus, Tags as TagsIcon, X } from "lucide-react";
import type {
  Tag,
  TagColor,
  TagWithUsage,
  TodoTagsSummary,
} from "./contract.d.ts";

const TAG_COLORS: readonly TagColor[] = [
  "slate",
  "sky",
  "emerald",
  "amber",
  "rose",
  "violet",
];

const TAG_COLOR_HEX: Readonly<Record<TagColor, string>> = {
  slate: "#64748b",
  sky: "#0284c7",
  emerald: "#059669",
  amber: "#d97706",
  rose: "#e11d48",
  violet: "#7c3aed",
};

const EMPTY_TAGS: readonly Tag[] = [];

interface SlotTaskProps {
  readonly task: { readonly id: string };
  readonly refresh: () => Promise<void>;
}

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const text = await response.text();
  const data = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  if (!response.ok) {
    const message =
      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(message);
  }
  return data as T;
}

type StoreStatus = "idle" | "loading" | "ready" | "error";

interface StoreSnapshot {
  readonly status: StoreStatus;
  readonly tags: readonly TagWithUsage[];
  readonly assignments: Readonly<Record<string, readonly Tag[]>>;
  readonly error: string;
}

const initialSnapshot: StoreSnapshot = {
  status: "idle",
  tags: [],
  assignments: {},
  error: "",
};

let snapshot: StoreSnapshot = initialSnapshot;
const listeners = new Set<() => void>();
let inflight: Promise<void> | null = null;

function publish(next: StoreSnapshot): void {
  snapshot = next;
  for (const listener of Array.from(listeners)) {
    listener();
  }
}

function describeError(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function loadSummary(): Promise<void> {
  if (inflight) return inflight;
  const pending = (async () => {
    if (snapshot.status !== "ready") {
      publish({ ...snapshot, status: "loading", error: "" });
    }
    try {
      const data = await requestJson<TodoTagsSummary>(
        "/api/app/todo-tags/summary",
      );
      publish({
        status: "ready",
        tags: data.tags ?? [],
        assignments: data.assignments ?? {},
        error: "",
      });
    } catch (error) {
      publish({ ...snapshot, status: "error", error: describeError(error) });
    } finally {
      inflight = null;
    }
  })();
  inflight = pending;
  return pending;
}

function ensureSummary(): Promise<void> {
  if (snapshot.status === "ready" || snapshot.status === "loading") {
    return inflight ?? Promise.resolve();
  }
  return loadSummary();
}

async function refreshSummary(): Promise<void> {
  if (inflight) {
    await inflight;
  }
  await loadSummary();
}

function useTagSummary(): StoreSnapshot {
  const [state, setState] = useState<StoreSnapshot>(snapshot);
  useEffect(() => {
    const listener = () => setState(snapshot);
    listeners.add(listener);
    listener();
    void ensureSummary();
    return () => {
      listeners.delete(listener);
    };
  }, []);
  return state;
}

function tagHex(color: string): string {
  return TAG_COLOR_HEX[color as TagColor] ?? TAG_COLOR_HEX.slate;
}

function TagChip({
  tag,
  onRemove,
}: {
  readonly tag: Tag;
  readonly onRemove?: () => void;
}) {
  const hex = tagHex(tag.color);
  return (
    <span
      data-todo-tag-chip={tag.id}
      data-todo-tag-name={tag.name}
      className="inline-flex max-w-[10rem] items-center gap-1 rounded-full border px-1.5 py-0.5 text-[11px] leading-4"
      style={{
        backgroundColor: `${hex}14`,
        borderColor: `${hex}66`,
        color: hex,
      }}
    >
      <span
        aria-hidden="true"
        className="size-1.5 shrink-0 rounded-full"
        style={{ backgroundColor: hex }}
      />
      <span className="truncate">{tag.name}</span>
      {onRemove && (
        <button
          type="button"
          onClick={onRemove}
          aria-label={`从任务移除标签 ${tag.name}`}
          className="inline-flex size-4 shrink-0 items-center justify-center rounded-full opacity-70 transition-opacity hover:bg-black/10 hover:opacity-100"
        >
          <X className="size-3" aria-hidden="true" />
        </button>
      )}
    </span>
  );
}

export function TodoTagBadges({ task }: SlotTaskProps) {
  const store = useTagSummary();
  const tags = store.assignments[task.id] ?? EMPTY_TAGS;
  if (tags.length === 0) return null;
  return (
    <span
      data-todo-tags-badges={task.id}
      className="flex flex-wrap items-center gap-1"
    >
      {tags.map((tag) => (
        <TagChip key={tag.id} tag={tag} />
      ))}
    </span>
  );
}

export function TodoTagEditor({ task }: SlotTaskProps) {
  const store = useTagSummary();
  const assigned = store.assignments[task.id] ?? EMPTY_TAGS;
  const assignedIds = useMemo(
    () => new Set(assigned.map((tag) => tag.id)),
    [assigned],
  );
  const [draft, setDraft] = useState("");
  const [draftColor, setDraftColor] = useState<TagColor>("sky");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const run = useCallback(async (operation: () => Promise<void>) => {
    setBusy(true);
    setError("");
    try {
      await operation();
      await refreshSummary();
    } catch (err) {
      setError(describeError(err));
    } finally {
      setBusy(false);
    }
  }, []);

  const taskTagsUrl = useMemo(
    () => `/api/app/todo-tags/tasks/${encodeURIComponent(task.id)}/tags`,
    [task.id],
  );

  const toggleTag = (tag: Tag) => {
    if (busy) return;
    void run(async () => {
      if (assignedIds.has(tag.id)) {
        await requestJson(`${taskTagsUrl}/${encodeURIComponent(tag.id)}`, {
          method: "DELETE",
        });
        return;
      }
      await requestJson(taskTagsUrl, {
        method: "POST",
        body: JSON.stringify({ tagId: tag.id }),
      });
    });
  };

  const handleCreateTag = () => {
    const name = draft.trim();
    if (!name || busy) return;
    void run(async () => {
      const created = await requestJson<{ tag: Tag }>(
        "/api/app/todo-tags/tags",
        {
          method: "POST",
          body: JSON.stringify({ name, color: draftColor }),
        },
      );
      await requestJson(taskTagsUrl, {
        method: "POST",
        body: JSON.stringify({ tagId: created.tag.id }),
      });
      setDraft("");
    });
  };

  const handleDeleteTag = (tag: Tag) => {
    if (busy) return;
    void run(async () => {
      await requestJson(
        `/api/app/todo-tags/tags/${encodeURIComponent(tag.id)}`,
        { method: "DELETE" },
      );
    });
  };

  return (
    <section data-todo-tags-editor={task.id} className="space-y-2.5">
      <div className="flex items-center justify-between gap-2">
        <h3 className="flex items-center gap-1.5 text-xs font-semibold text-ink">
          <TagsIcon className="size-3.5 text-muted" aria-hidden="true" />
          <span>标签</span>
        </h3>
        <span className="text-[11px] text-muted">
          {assigned.length > 0 ? `已选 ${assigned.length} 个` : "未添加"}
        </span>
      </div>

      {store.status === "error" && (
        <div className="flex items-center justify-between gap-2 rounded-md border border-danger/25 bg-danger/5 px-2.5 py-1.5 text-xs text-danger">
          <span className="min-w-0 truncate">
            {store.error || "标签加载失败"}
          </span>
          <button
            type="button"
            onClick={() => void loadSummary()}
            className="shrink-0 font-medium underline decoration-dotted underline-offset-2"
          >
            重试
          </button>
        </div>
      )}

      {store.status === "loading" && store.tags.length === 0 && (
        <p className="text-xs text-muted">正在加载标签…</p>
      )}

      {assigned.length > 0 && (
        <div className="flex flex-wrap gap-1.5">
          {assigned.map((tag) => (
            <TagChip key={tag.id} tag={tag} onRemove={() => toggleTag(tag)} />
          ))}
        </div>
      )}

      {store.tags.length > 0 && (
        <div className="space-y-1">
          <p className="text-[11px] font-medium text-muted">标签库</p>
          <div
            role="group"
            aria-label="标签库"
            className="flex flex-wrap gap-1.5"
          >
            {store.tags.map((tag) => {
              const active = assignedIds.has(tag.id);
              const hex = tagHex(tag.color);
              return (
                <span
                  key={tag.id}
                  className="inline-flex items-center overflow-hidden rounded-full border border-line text-[11px]"
                  style={{
                    borderColor: active ? hex : undefined,
                    backgroundColor: active ? `${hex}18` : undefined,
                    color: active ? hex : undefined,
                  }}
                >
                  <button
                    type="button"
                    disabled={busy}
                    onClick={() => toggleTag(tag)}
                    aria-pressed={active}
                    data-todo-tag-toggle={tag.id}
                    title={
                      active ? `移除标签 ${tag.name}` : `添加标签 ${tag.name}`
                    }
                    className={`inline-flex items-center gap-1 px-2 py-1 transition-colors disabled:opacity-50 ${
                      active ? "font-medium" : "text-muted hover:text-ink"
                    }`}
                  >
                    {active ? (
                      <Check className="size-3" aria-hidden="true" />
                    ) : (
                      <Plus className="size-3" aria-hidden="true" />
                    )}
                    <span className="max-w-[8rem] truncate">{tag.name}</span>
                  </button>
                  <button
                    type="button"
                    disabled={busy}
                    onClick={() => handleDeleteTag(tag)}
                    aria-label={`删除标签 ${tag.name}`}
                    title={`删除标签 ${tag.name}`}
                    className="inline-flex items-center self-stretch border-l border-line/70 px-1 text-muted transition-colors hover:bg-danger/10 hover:text-danger disabled:opacity-50"
                  >
                    <X className="size-3" aria-hidden="true" />
                  </button>
                </span>
              );
            })}
          </div>
        </div>
      )}

      {store.status === "ready" && store.tags.length === 0 && (
        <p className="text-xs text-muted">
          还没有标签，创建一个并直接添加到任务。
        </p>
      )}

      <div className="space-y-1.5">
        <div className="flex items-center gap-1.5">
          <input
            type="text"
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Enter") {
                event.preventDefault();
                handleCreateTag();
              }
            }}
            placeholder="新建标签名称"
            aria-label="新建标签名称"
            maxLength={32}
            disabled={busy}
            data-todo-tag-input="true"
            className="min-h-9 min-w-0 flex-1 rounded-md border border-line bg-surface px-2.5 py-1.5 text-xs text-ink outline-none focus:border-accent focus:ring-1 focus:ring-accent disabled:opacity-60"
          />
          <button
            type="button"
            onClick={handleCreateTag}
            disabled={busy || !draft.trim()}
            data-todo-tag-create="true"
            className="inline-flex min-h-9 shrink-0 items-center gap-1 rounded-md bg-accent px-2.5 text-xs font-medium text-surface transition-colors hover:bg-accent/90 disabled:opacity-45"
          >
            <Plus className="size-3.5" aria-hidden="true" />
            <span>创建并添加</span>
          </button>
        </div>
        <div
          className="flex items-center gap-1.5"
          role="group"
          aria-label="标签颜色"
        >
          {TAG_COLORS.map((color) => (
            <button
              key={color}
              type="button"
              disabled={busy}
              onClick={() => setDraftColor(color)}
              aria-label={`选择颜色 ${color}`}
              aria-pressed={draftColor === color}
              data-todo-tag-color={color}
              className={`size-5 rounded-full border-2 transition-transform disabled:opacity-50 ${
                draftColor === color
                  ? "scale-110 border-ink"
                  : "border-transparent"
              }`}
              style={{ backgroundColor: tagHex(color) }}
            />
          ))}
        </div>
      </div>

      {error && (
        <p role="alert" className="text-xs text-danger">
          {error}
        </p>
      )}
    </section>
  );
}

export default function apply(ctx: Context): void {
  ctx.slots.register("todo.item.badges", TodoTagBadges);
  ctx.slots.register("todo.item.detail", TodoTagEditor);
}
"}, "testFiles": {"todo-tags.spec.ts": "import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

interface TagShape {
  readonly id: string;
  readonly name: string;
  readonly color: string;
}

interface TaskTagsBody {
  readonly tags: TagShape[];
}

interface SummaryBody {
  readonly tags: ReadonlyArray<TagShape & { readonly taskCount: number }>;
  readonly assignments: Readonly<Record<string, TagShape[]>>;
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const suffix = Math.random().toString(36).slice(2, 8);
  const firstName = `Important-${suffix}`;
  const secondName = `Later-${suffix}`;

  const taskResponse = await ctx.request({
    method: "POST",
    path: "/api/app/todo-core/tasks",
    body: { title: `Tagged Task ${suffix}` },
  });
  assert.equal(taskResponse.status, 201);
  const taskId = (taskResponse.body as { task: { id: string } }).task.id;

  const initialList = await ctx.request({
    method: "GET",
    path: "/api/app/todo-tags/tags",
  });
  assert.equal(initialList.status, 200);
  assert.ok(Array.isArray((initialList.body as { tags?: unknown }).tags));

  const created = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: firstName, color: "rose" },
  });
  assert.equal(created.status, 201);
  const important = (created.body as { tag: TagShape }).tag;
  assert.equal(important.name, firstName);
  assert.equal(important.color, "rose");

  const second = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: secondName, color: "sky" },
  });
  assert.equal(second.status, 201);
  const later = (second.body as { tag: TagShape }).tag;

  const duplicate = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: firstName.toUpperCase() },
  });
  assert.equal(duplicate.status, 409);

  const badColor = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: `Neon-${suffix}`, color: "neon" },
  });
  assert.equal(badColor.status, 400);

  const attached = await ctx.request({
    method: "POST",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagId: important.id },
  });
  assert.equal(attached.status, 200);
  assert.deepEqual(
    (attached.body as TaskTagsBody).tags.map((tag) => tag.name),
    [firstName],
  );

  const listed = await ctx.request({
    method: "GET",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
  });
  assert.equal(listed.status, 200);
  assert.equal((listed.body as TaskTagsBody).tags.length, 1);

  const summary = await ctx.request({
    method: "GET",
    path: "/api/app/todo-tags/summary",
  });
  assert.equal(summary.status, 200);
  const summaryBody = summary.body as SummaryBody;
  assert.deepEqual(
    (summaryBody.assignments[taskId] ?? []).map((tag) => tag.name),
    [firstName],
  );
  assert.equal(
    summaryBody.tags.find((tag) => tag.id === important.id)?.taskCount,
    1,
  );

  const replaced = await ctx.request({
    method: "PUT",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagIds: [later.id, important.id] },
  });
  assert.equal(replaced.status, 200);
  assert.deepEqual(
    (replaced.body as TaskTagsBody).tags.map((tag) => tag.name),
    [firstName, secondName],
  );

  const missingTask = await ctx.request({
    method: "GET",
    path: "/api/app/todo-tags/tasks/missing-task/tags",
  });
  assert.equal(missingTask.status, 404);

  const unknownTag = await ctx.request({
    method: "POST",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagId: "missing-tag" },
  });
  assert.equal(unknownTag.status, 404);

  const deleted = await ctx.request({
    method: "DELETE",
    path: `/api/app/todo-tags/tags/${important.id}`,
  });
  assert.equal(deleted.status, 200);

  const afterTagDelete = await ctx.request({
    method: "GET",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
  });
  assert.deepEqual(
    (afterTagDelete.body as TaskTagsBody).tags.map((tag) => tag.name),
    [secondName],
  );

  const deletedTask = await ctx.request({
    method: "DELETE",
    path: `/api/app/todo-core/tasks/${taskId}`,
  });
  assert.equal(deletedTask.status, 200);

  const pruned = await ctx.request({
    method: "GET",
    path: "/api/app/todo-tags/summary",
  });
  const prunedBody = pruned.body as SummaryBody;
  assert.equal(prunedBody.assignments[taskId], undefined);
  assert.equal(
    prunedBody.tags.find((tag) => tag.id === later.id)?.taskCount,
    0,
  );
}
"}}]}

