    "summary",
  );
  const summaryBody = summary.body as SummaryBody;
  assert.deepEqual(
    (summaryBody.assignments[taskId] ?? []).map((tag) => tag.name),
    [firstName],
  );
  assert.equal(
    summaryBody.tags.find((tag) => tag.id === important.id)?.taskCount,
    1,
  );

  const replaced = await expectStatus(
    ctx.request({
      method: "PUT",
      path: `/api/app/todo-tags/tasks/${taskId}/tags`,
      body: { tagIds: [later.id, important.id] },
    }),
    200,
    "replace task tags (PUT)",
  );
  assert.deepEqual(
    (replaced.body as TaskTagsBody).tags.map((tag) => tag.name),
    [firstName, secondName],
  );

  await expectStatus(
    ctx.request({
      method: "GET",
      path: "/api/app/todo-tags/tasks/missing-task/tags",
    }),
