import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

interface TagShape {
  readonly id: string;
  readonly name: string;
  readonly color: string;
}

interface TaskTagsBody {
  readonly tags: TagShape[];
}

interface SummaryBody {
  readonly tags: ReadonlyArray<TagShape & { readonly taskCount: number }>;
  readonly assignments: Readonly<Record<string, TagShape[]>>;
}

interface SimpleResponse {
  readonly status: number;
  readonly body: unknown;
}

async function expectStatus(
  pending: Promise<SimpleResponse>,
  expected: number,
  label: string,
): Promise<SimpleResponse> {
  const response = await pending;
  assert.equal(
    response.status,
    expected,
    `${label}: expected ${expected}, received ${response.status}; body=${JSON.stringify(response.body)}`,
  );
  return response;
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const suffix = Math.random().toString(36).slice(2, 8);
  const firstName = `Important-${suffix}`;
  const secondName = `Later-${suffix}`;

  const taskResponse = await expectStatus(
    ctx.request({
      method: "POST",
      path: "/api/app/todo-core/tasks",
      body: { title: `Tagged Task ${suffix}` },
    }),
    201,
    "create task (todo-core)",
  );
  const taskId = (taskResponse.body as { task: { id: string } }).task.id;

  await expectStatus(
    ctx.request({ method: "GET", path: "/api/app/todo-tags/tags" }),
    200,
    "list tags",
  );

  const created = await expectStatus(
    ctx.request({
      method: "POST",
      path: "/api/app/todo-tags/tags",
      body: { name: firstName, color: "rose" },
    }),
    201,
    "create first tag",
  );
  const important = (created.body as { tag: TagShape }).tag;
  assert.equal(important.name, firstName);
  assert.equal(important.color, "rose");

  const second = await expectStatus(
    ctx.request({
      method: "POST",
      path: "/api/app/todo-tags/tags",
      body: { name: secondName, color: "sky" },
    }),
    201,
    "create second tag",
  );
  const later = (second.body as { tag: TagShape }).tag;

  await expectStatus(
    ctx.request({
      method: "POST",
      path: "/api/app/todo-tags/tags",
      body: { name: firstName.toUpperCase() },
    }),
    409,
    "reject duplicate tag name",
  );

  await expectStatus(
    ctx.request({
      method: "POST",
      path: "/api/app/todo-tags/tags",
      body: { name: `Neon-${suffix}`, color: "neon" },
    }),
    400,
    "reject invalid tag color",
  );

  const attached = await expectStatus(
    ctx.request({
      method: "POST",
      path: `/api/app/todo-tags/tasks/${taskId}/tags`,
      body: { tagId: important.id },
    }),
    200,
    "attach tag",
  );
  assert.deepEqual(
    (attached.body as TaskTagsBody).tags.map((tag) => tag.name),
    [firstName],
  );

  const listed = await expectStatus(
    ctx.request({
      method: "GET",
      path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    }),
    200,
    "list task tags",
  );
  assert.equal((listed.body as TaskTagsBody).tags.length, 1);

  const summary = await expectStatus(
    ctx.request({ method: "GET", path: "/api/app/todo-tags/summary" }),
    200,
    "summary",
  );
  const summaryBody = summary.body as SummaryBody;
  assert.deepEqual(
    (summaryBody.assignments[taskId] ?? []).map((tag) => tag.name),
    [firstName],
  );
  assert.equal(
    summaryBody.tags.find((tag) => tag.id === important.id)?.taskCount,
    1,
  );

  const replaced = await expectStatus(
    ctx.request({
      method: "PUT",
      path: `/api/app/todo-tags/tasks/${taskId}/tags`,
      body: { tagIds: [later.id, important.id] },
    }),
    200,
    "replace task tags (PUT)",
  );
  assert.deepEqual(
    (replaced.body as TaskTagsBody).tags.map((tag) => tag.name),
    [firstName, secondName],
  );

  await expectStatus(
    ctx.request({
      method: "GET",
      path: "/api/app/todo-tags/tasks/missing-task/tags",
    }),
    404,
    "missing task",
  );

  await expectStatus(
    ctx.request({
      method: "POST",
      path: `/api/app/todo-tags/tasks/${taskId}/tags`,
      body: { tagId: "missing-tag" },
    }),
    404,
    "unknown tag",
  );

  await expectStatus(
    ctx.request({
      method: "DELETE",
      path: `/api/app/todo-tags/tags/${important.id}`,
    }),
    200,
    "delete tag",
  );

  const afterTagDelete = await expectStatus(
    ctx.request({
      method: "GET",
      path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    }),
    200,
    "list after tag delete",
  );
  assert.deepEqual(
    (afterTagDelete.body as TaskTagsBody).tags.map((tag) => tag.name),
    [secondName],
  );

  await expectStatus(
    ctx.request({
      method: "DELETE",
      path: `/api/app/todo-core/tasks/${taskId}`,
    }),
    200,
    "delete task (todo-core)",
  );

  const pruned = await expectStatus(
    ctx.request({ method: "GET", path: "/api/app/todo-tags/summary" }),
    200,
    "summary after task delete",
  );
  const prunedBody = pruned.body as SummaryBody;
  assert.equal(prunedBody.assignments[taskId], undefined);
  assert.equal(
    prunedBody.tags.find((tag) => tag.id === later.id)?.taskCount,
    0,
  );
}

